const BORDER = `<use href="#pa-bu" x="640" y="300"/><use href="#pa-bu" transform="translate(640 300) scale(-1 1)"/><use href="#pa-bu" x="832" y="300"/><use href="#pa-bu" transform="translate(448 300) scale(-1 1)"/><use href="#pa-bu" x="1024" y="300"/><use href="#pa-bu" transform="translate(256 300) scale(-1 1)"/><use href="#pa-bu" x="1216" y="300"/><use href="#pa-bu" transform="translate(64 300) scale(-1 1)"/><use href="#pa-bc" x="640" y="300"/>`

const at = walker(PATH)
const offset = ref(0)
const figures = computed(() =>
  ORDER.map((f) => {
    const p = at(f.s + offset.value)
    const x = p.dir > 0 ? p.x - f.w : p.x + f.w
    return { href: '#pa-' + f.n, t: `translate(${x.toFixed(1)} ${p.y.toFixed(1)}) scale(${(p.dir * f.k).toFixed(3)} ${f.k})` }
  }),
)

let raf = 0
onMounted(() => {
  const still = typeof matchMedia === 'function' && matchMedia('(prefers-reduced-motion: reduce)').matches
  if (!props.walk || still) return
  const from = -64, dur = 2600, t0 = performance.now()
  offset.value = from
  const step = (now: number) => {
    const u = Math.min(1, (now - t0) / dur)
    offset.value = from * Math.pow(1 - u, 3)
    if (u < 1) raf = requestAnimationFrame(step)
  }
  raf = requestAnimationFrame(step)
})
onBeforeUnmount(() => cancelAnimationFrame(raf))
</script>

