    <path v-if="meadow" fill="#DCE2D2" :d="MEADOW" />
    <g v-html="SCENE" />
    <use v-for="(f, i) in figures" :key="i" :href="f.href" :transform="f.t" />
    <svg width="1280" height="330" overflow="hidden" v-html="BORDER" />
  </svg>
</template>

